type Test = { input: unknown; expected: Record<string, unknown>[]; ordered?: boolean };
type SparkQuestion = {
  id: string; learning_level: "A" | "B" | "C"; title: string; topic: string; subtopic: string;
  function_name: string; params: string[]; input_description: string; output_description: string;
  reference_solution: string; explanation: string; hints: string[];
  public_input: unknown; public_expected: Record<string, unknown>[]; cases: Test[];
};

function buildQuestion(question: SparkQuestion, index: number) {
  const signature = question.params.join(", ");
  const starter = `from pyspark.sql import functions as F\n\ndef ${question.function_name}(${signature}):\n    # ${question.hints[0]}\n    pass\n`;
  return {
    id: question.id,
    module_id: "pyspark-foundations",
    learning_level: question.learning_level,
    level_title: `Level ${question.learning_level}`,
    topic: question.topic,
    subtopic: question.subtopic,
    tags: ["pyspark", `level-${question.learning_level.toLowerCase()}`, ...question.topic.toLowerCase().split(/[^a-z0-9]+/).filter(Boolean)],
    difficulty: question.learning_level === "A" ? "beginner" : question.learning_level === "B" ? "intermediate" : "advanced",
    type: "coding",
    language: "pyspark",
    function_name: question.function_name,
    title: question.title,
    prompt: `Level ${question.learning_level} · Exercise ${String(index).padStart(2, "0")}\n\n${question.explanation}`,
    starter_code: starter,
    input_description: question.input_description,
    output_description: question.output_description,
    public_examples: [{ input: question.public_input, expected: question.public_expected }],
    test_cases: question.cases.map((test, testIndex) => ({ name: `hidden_case_${testIndex + 1}`, input: test.input, expected: test.expected, ordered: test.ordered ?? false })),
    reference_solution: question.reference_solution,
    explanation: question.explanation,
    common_mistakes: ["Collecting source rows to the Python driver", "Returning a Python collection instead of a Spark DataFrame"],
    hints: question.hints,
    status: "published",
    created_at: new Date("2026-10-19T00:00:00.000Z"),
    updated_at: new Date("2026-10-19T00:00:00.000Z")
  };
}

const levelA: SparkQuestion[] = [
  { id:"pyspark-a01-select-columns", learning_level:"A", title:"Select employee names", topic:"DataFrame basics", subtopic:"select", function_name:"level_a_01_select_employee_names", params:["employees"], input_description:"employees has employee_id, first_name, last_name.", output_description:"first_name and last_name for every employee.", public_input:[{employee_id:1,first_name:"Maya",last_name:"Chen"},{employee_id:2,first_name:"Omar",last_name:"Ali"}], public_expected:[{first_name:"Maya",last_name:"Chen"},{first_name:"Omar",last_name:"Ali"}], cases:[{input:[{employee_id:3,first_name:"Inez",last_name:"Park"}],expected:[{first_name:"Inez",last_name:"Park"}]},{input:[{employee_id:4,first_name:"Noah",last_name:"Singh"},{employee_id:5,first_name:"Eva",last_name:"Jones"}],expected:[{first_name:"Noah",last_name:"Singh"},{first_name:"Eva",last_name:"Jones"}]}], reference_solution:"def level_a_01_select_employee_names(employees):\n    return employees.select(\"first_name\", \"last_name\")\n", explanation:"A Spark DataFrame is a distributed table. select() creates a new DataFrame containing only the requested columns.", hints:["Call select() on the input DataFrame.","Pass the two requested column names as strings."] },
  { id:"pyspark-a02-filter-salary", learning_level:"A", title:"Find salaries above a threshold", topic:"DataFrame basics", subtopic:"filter", function_name:"level_a_02_filter_salary", params:["employees"], input_description:"employees has employee_id, name, salary.", output_description:"Rows with salary at least 60000.", public_input:[{employee_id:1,name:"Kai",salary:52000},{employee_id:2,name:"Rin",salary:76000}], public_expected:[{employee_id:2,name:"Rin",salary:76000}], cases:[{input:[{employee_id:3,name:"Ari",salary:60000},{employee_id:4,name:"Bo",salary:59999}],expected:[{employee_id:3,name:"Ari",salary:60000}]},{input:[{employee_id:5,name:"Uma",salary:90000}],expected:[{employee_id:5,name:"Uma",salary:90000}]}], reference_solution:"from pyspark.sql import functions as F\ndef level_a_02_filter_salary(employees):\n    return employees.filter(F.col(\"salary\") >= 60000)\n", explanation:"filter() keeps only rows where its Spark column expression evaluates true. The >= operator includes the threshold itself.", hints:["Use filter() with a column expression.","Compare salary with >= 60000."] },
  { id:"pyspark-a03-sort-names", learning_level:"A", title:"Sort customers by name", topic:"DataFrame basics", subtopic:"orderBy", function_name:"level_a_03_sort_names", params:["customers"], input_description:"customers has customer_id and name.", output_description:"All rows ordered by name ascending.", public_input:[{customer_id:1,name:"Zoe"},{customer_id:2,name:"Ada"}], public_expected:[{customer_id:2,name:"Ada"},{customer_id:1,name:"Zoe"}], cases:[{input:[{customer_id:3,name:"Mina"},{customer_id:4,name:"Bea"}],expected:[{customer_id:4,name:"Bea"},{customer_id:3,name:"Mina"}],ordered:true},{input:[{customer_id:5,name:"Lee"}],expected:[{customer_id:5,name:"Lee"}],ordered:true}], reference_solution:"def level_a_03_sort_names(customers):\n    return customers.orderBy(\"name\")\n", explanation:"orderBy() sorts the DataFrame by a column. Ascending order is the default.", hints:["Use orderBy() on the DataFrame.","Sort using the name column."] },
  { id:"pyspark-a04-add-constant-column", learning_level:"A", title:"Add a source label", topic:"DataFrame basics", subtopic:"withColumn and lit", function_name:"level_a_04_add_source_label", params:["events"], input_description:"events has event_id and event_type.", output_description:"Keep all input columns and add source='practice'.", public_input:[{event_id:1,event_type:"view"}], public_expected:[{event_id:1,event_type:"view",source:"practice"}], cases:[{input:[{event_id:2,event_type:"click"}],expected:[{event_id:2,event_type:"click",source:"practice"}]},{input:[{event_id:3,event_type:"buy"},{event_id:4,event_type:"view"}],expected:[{event_id:3,event_type:"buy",source:"practice"},{event_id:4,event_type:"view",source:"practice"}]}], reference_solution:"from pyspark.sql import functions as F\ndef level_a_04_add_source_label(events):\n    return events.withColumn(\"source\", F.lit(\"practice\"))\n", explanation:"withColumn() adds or replaces a column. lit() creates a Spark literal that is applied to every row.", hints:["Use withColumn() to add a field.","Wrap the constant string with F.lit()."] },
  { id:"pyspark-a05-drop-column", learning_level:"A", title:"Remove a temporary field", topic:"DataFrame basics", subtopic:"drop", function_name:"level_a_05_drop_debug", params:["events"], input_description:"events has event_id, event_type, debug_note.", output_description:"Keep the event fields and remove debug_note.", public_input:[{event_id:1,event_type:"view",debug_note:"raw"}], public_expected:[{event_id:1,event_type:"view"}], cases:[{input:[{event_id:2,event_type:"click",debug_note:"x"}],expected:[{event_id:2,event_type:"click"}]},{input:[{event_id:3,event_type:"purchase",debug_note:"y"}],expected:[{event_id:3,event_type:"purchase"}]}], reference_solution:"def level_a_05_drop_debug(events):\n    return events.drop(\"debug_note\")\n", explanation:"drop() removes a column from a DataFrame without changing the source DataFrame.", hints:["Call drop() on the DataFrame.","Provide the temporary column name."] },
  { id:"pyspark-a06-fill-null", learning_level:"A", title:"Fill a missing city", topic:"Null handling", subtopic:"fillna", function_name:"level_a_06_fill_city", params:["customers"], input_description:"customers has customer_id and city; city may be null.", output_description:"Replace null city values with 'Unknown'.", public_input:[{customer_id:1,city:"Oslo"},{customer_id:2,city:null}], public_expected:[{customer_id:1,city:"Oslo"},{customer_id:2,city:"Unknown"}], cases:[{input:[{customer_id:3,city:null}],expected:[{customer_id:3,city:"Unknown"}]},{input:[{customer_id:4,city:"Lima"}],expected:[{customer_id:4,city:"Lima"}]}], reference_solution:"def level_a_06_fill_city(customers):\n    return customers.fillna({\"city\": \"Unknown\"})\n", explanation:"fillna() replaces nulls with a chosen value. A mapping limits the replacement to one column.", hints:["Use fillna() with a dictionary.","Map city to the fallback string."] },
  { id:"pyspark-a07-remove-duplicates", learning_level:"A", title:"Remove duplicate event rows", topic:"DataFrame basics", subtopic:"dropDuplicates", function_name:"level_a_07_unique_events", params:["events"], input_description:"events has event_id and event_type.", output_description:"One row per distinct event_id and event_type pair.", public_input:[{event_id:1,event_type:"view"},{event_id:1,event_type:"view"},{event_id:2,event_type:"click"}], public_expected:[{event_id:1,event_type:"view"},{event_id:2,event_type:"click"}], cases:[{input:[{event_id:3,event_type:"buy"},{event_id:3,event_type:"buy"}],expected:[{event_id:3,event_type:"buy"}]},{input:[{event_id:4,event_type:"view"},{event_id:5,event_type:"view"}],expected:[{event_id:4,event_type:"view"},{event_id:5,event_type:"view"}]}], reference_solution:"def level_a_07_unique_events(events):\n    return events.dropDuplicates([\"event_id\", \"event_type\"])\n", explanation:"dropDuplicates() removes rows that match on the specified columns while preserving distinct records.", hints:["Use dropDuplicates().","Pass the columns that define one unique event."] },
  { id:"pyspark-a08-count-rows", learning_level:"A", title:"Count the rows in a batch", topic:"DataFrame basics", subtopic:"count", function_name:"level_a_08_count_rows", params:["events"], input_description:"events is a DataFrame of event records.", output_description:"A one-row DataFrame with an integer row_count column.", public_input:[{event_id:1},{event_id:2},{event_id:3}], public_expected:[{row_count:3}], cases:[{input:[{event_id:9}],expected:[{row_count:1}]},{input:[{event_id:7},{event_id:8}],expected:[{row_count:2}]}], reference_solution:"from pyspark.sql import functions as F\ndef level_a_08_count_rows(events):\n    return events.agg(F.count(\"*\").alias(\"row_count\"))\n", explanation:"A DataFrame aggregation can count rows and return the result as another DataFrame.", hints:["Use agg() with F.count('*').","Give the result column the name row_count."] },
  { id:"pyspark-a09-uppercase", learning_level:"A", title:"Uppercase event types", topic:"String functions", subtopic:"upper", function_name:"level_a_09_uppercase_types", params:["events"], input_description:"events has event_type text.", output_description:"Keep rows and add event_type_upper.", public_input:[{event_type:"page_view"},{event_type:"purchase"}], public_expected:[{event_type:"page_view",event_type_upper:"PAGE_VIEW"},{event_type:"purchase",event_type_upper:"PURCHASE"}], cases:[{input:[{event_type:"click"}],expected:[{event_type:"click",event_type_upper:"CLICK"}]},{input:[{event_type:"signup"}],expected:[{event_type:"signup",event_type_upper:"SIGNUP"}]}], reference_solution:"from pyspark.sql import functions as F\ndef level_a_09_uppercase_types(events):\n    return events.withColumn(\"event_type_upper\", F.upper(\"event_type\"))\n", explanation:"Spark SQL string functions operate on columns across the DataFrame without a Python row loop.", hints:["Use withColumn() to add the output field.","Apply F.upper() to event_type."] },
  { id:"pyspark-a10-name-length", learning_level:"A", title:"Measure customer names", topic:"String functions", subtopic:"length", function_name:"level_a_10_name_length", params:["customers"], input_description:"customers has customer_id and name.", output_description:"Add name_length containing the character count.", public_input:[{customer_id:1,name:"Ada"},{customer_id:2,name:"Mika"}], public_expected:[{customer_id:1,name:"Ada",name_length:3},{customer_id:2,name:"Mika",name_length:4}], cases:[{input:[{customer_id:3,name:"Li"}],expected:[{customer_id:3,name:"Li",name_length:2}]},{input:[{customer_id:4,name:"Noah"}],expected:[{customer_id:4,name:"Noah",name_length:4}]}], reference_solution:"from pyspark.sql import functions as F\ndef level_a_10_name_length(customers):\n    return customers.withColumn(\"name_length\", F.length(\"name\"))\n", explanation:"F.length() computes a string length as a Spark expression.", hints:["Add a column with withColumn().","Use F.length() on the name column."] },
  { id:"pyspark-a11-when-label", learning_level:"A", title:"Label large orders", topic:"Conditional columns", subtopic:"when and otherwise", function_name:"level_a_11_order_label", params:["orders"], input_description:"orders has order_id and amount.", output_description:"Add size_label='large' for amount >= 100, otherwise 'small'.", public_input:[{order_id:1,amount:120},{order_id:2,amount:35}], public_expected:[{order_id:1,amount:120,size_label:"large"},{order_id:2,amount:35,size_label:"small"}], cases:[{input:[{order_id:3,amount:100}],expected:[{order_id:3,amount:100,size_label:"large"}]},{input:[{order_id:4,amount:99}],expected:[{order_id:4,amount:99,size_label:"small"}]}], reference_solution:"from pyspark.sql import functions as F\ndef level_a_11_order_label(orders):\n    label = F.when(F.col(\"amount\") >= 100, F.lit(\"large\")).otherwise(F.lit(\"small\"))\n    return orders.withColumn(\"size_label\", label)\n", explanation:"when()/otherwise() implements if/else logic as a Spark column expression.", hints:["Start with F.when(condition, value).","Finish the expression with otherwise()."] },
  { id:"pyspark-a12-cast-age", learning_level:"A", title:"Convert age text to an integer", topic:"Data types", subtopic:"cast", function_name:"level_a_12_cast_age", params:["people"], input_description:"people has person_id and age_text containing numeric text.", output_description:"Add age as an integer while preserving age_text.", public_input:[{person_id:1,age_text:"28"}], public_expected:[{person_id:1,age_text:"28",age:28}], cases:[{input:[{person_id:2,age_text:"41"}],expected:[{person_id:2,age_text:"41",age:41}]},{input:[{person_id:3,age_text:"19"}],expected:[{person_id:3,age_text:"19",age:19}]}], reference_solution:"from pyspark.sql import functions as F\ndef level_a_12_cast_age(people):\n    return people.withColumn(\"age\", F.col(\"age_text\").cast(\"int\"))\n", explanation:"cast() converts a column to a Spark SQL type. Explicit types are safer than leaving numeric strings unconverted.", hints:["Use withColumn() for the new field.","Cast age_text to int."] },
  { id:"pyspark-a13-filter-prefix", learning_level:"A", title:"Find email addresses from a domain", topic:"Filtering", subtopic:"startswith", function_name:"level_a_13_filter_domain", params:["users"], input_description:"users has user_id and email.", output_description:"Keep email addresses that start with 'data@'.", public_input:[{user_id:1,email:"data@one.test"},{user_id:2,email:"sales@two.test"}], public_expected:[{user_id:1,email:"data@one.test"}], cases:[{input:[{user_id:3,email:"data@three.test"}],expected:[{user_id:3,email:"data@three.test"}]},{input:[{user_id:4,email:"ops@four.test"}],expected:[]}], reference_solution:"from pyspark.sql import functions as F\ndef level_a_13_filter_domain(users):\n    return users.filter(F.col(\"email\").startswith(\"data@\"))\n", explanation:"String column methods such as startswith() can be used directly in a distributed filter.", hints:["Filter on the email column.","Use startswith('data@')."] },
  { id:"pyspark-a14-group-count", learning_level:"A", title:"Count events by type", topic:"GroupBy basics", subtopic:"groupBy and count", function_name:"level_a_14_event_counts", params:["events"], input_description:"events has a non-null event_type string.", output_description:"One row per event_type with a count, sorted by event_type.", public_input:[{event_type:"view"},{event_type:"buy"},{event_type:"view"}], public_expected:[{event_type:"buy",count:1},{event_type:"view",count:2}], cases:[{input:[{event_type:"click"},{event_type:"click"}],expected:[{event_type:"click",count:2}],ordered:true},{input:[{event_type:"view"},{event_type:"buy"}],expected:[{event_type:"buy",count:1},{event_type:"view",count:1}],ordered:true}], reference_solution:"def level_a_14_event_counts(events):\n    return events.groupBy(\"event_type\").count().orderBy(\"event_type\")\n", explanation:"groupBy() creates groups by key, count() aggregates each group, and orderBy() makes the result order explicit.", hints:["Group on event_type.","Call count(), then sort by event_type."] },
  { id:"pyspark-a15-fill-score", learning_level:"A", title:"Replace a missing score", topic:"Null handling", subtopic:"coalesce", function_name:"level_a_15_fill_score", params:["scores"], input_description:"scores has student_id and nullable score.", output_description:"Replace null score with integer zero and sort by student_id.", public_input:[{student_id:1,score:88},{student_id:2,score:null}], public_expected:[{student_id:1,score:88},{student_id:2,score:0}], cases:[{input:[{student_id:3,score:null}],expected:[{student_id:3,score:0}]},{input:[{student_id:4,score:70}],expected:[{student_id:4,score:70}]}], reference_solution:"from pyspark.sql import functions as F\ndef level_a_15_fill_score(scores):\n    return scores.withColumn(\"score\", F.coalesce(F.col(\"score\"), F.lit(0))).orderBy(\"student_id\")\n", explanation:"coalesce() returns the first non-null expression. A literal zero supplies a numeric fallback while retaining the other fields.", hints:["Use withColumn() to replace score.","Choose between the column value and F.lit(0) with coalesce()."] }
];

const levelB: SparkQuestion[] = [
  { id:"pyspark-b01-join-customer-orders", learning_level:"B", title:"Join orders to customer names", topic:"Joins", subtopic:"inner join", function_name:"level_b_01_join_customers", params:["orders","customers"], input_description:"orders has order_id, customer_id, amount; customers has customer_id, customer_name.", output_description:"Return order_id, customer_name, amount ordered by order_id.", public_input:{orders:[{order_id:1,customer_id:10,amount:25}],customers:[{customer_id:10,customer_name:"Nia"}]}, public_expected:[{order_id:1,customer_name:"Nia",amount:25}], cases:[{input:{orders:[{order_id:2,customer_id:20,amount:40}],customers:[{customer_id:20,customer_name:"Ravi"}]},expected:[{order_id:2,customer_name:"Ravi",amount:40}],ordered:true},{input:{orders:[{order_id:3,customer_id:30,amount:15}],customers:[{customer_id:30,customer_name:"Lee"}]},expected:[{order_id:3,customer_name:"Lee",amount:15}],ordered:true}], reference_solution:"def level_b_01_join_customers(orders, customers):\n    return (orders.join(customers, \"customer_id\", \"inner\")\n            .select(\"order_id\", \"customer_name\", \"amount\")\n            .orderBy(\"order_id\"))\n", explanation:"Join keys connect rows across DataFrames. An inner join keeps only matching customer/order pairs.", hints:["Join using customer_id.","Select only the required fields and sort by order_id."] },
  { id:"pyspark-b02-revenue-by-city", learning_level:"B", title:"Total order amount by city", topic:"Aggregations", subtopic:"groupBy and sum", function_name:"level_b_02_revenue_by_city", params:["orders","customers"], input_description:"Join orders (customer_id, amount) to customers (customer_id, city).", output_description:"Return city and total_amount sorted by city.", public_input:{orders:[{customer_id:1,amount:10},{customer_id:1,amount:5},{customer_id:2,amount:8}],customers:[{customer_id:1,city:"Lima"},{customer_id:2,city:"Oslo"}]}, public_expected:[{city:"Lima",total_amount:15},{city:"Oslo",total_amount:8}], cases:[{input:{orders:[{customer_id:3,amount:12}],customers:[{customer_id:3,city:"Riga"}]},expected:[{city:"Riga",total_amount:12}],ordered:true},{input:{orders:[{customer_id:4,amount:2},{customer_id:4,amount:3}],customers:[{customer_id:4,city:"Bern"}]},expected:[{city:"Bern",total_amount:5}],ordered:true}], reference_solution:"from pyspark.sql import functions as F\ndef level_b_02_revenue_by_city(orders, customers):\n    return (orders.join(customers, \"customer_id\")\n            .groupBy(\"city\").agg(F.sum(\"amount\").alias(\"total_amount\"))\n            .orderBy(\"city\"))\n", explanation:"Join the city dimension before grouping. sum() aggregates all order amounts for each city.", hints:["Join orders and customers on customer_id.","Group by city and sum amount."] },
  { id:"pyspark-b03-average-rating", learning_level:"B", title:"Average rating per product", topic:"Aggregations", subtopic:"avg", function_name:"level_b_03_average_rating", params:["reviews"], input_description:"reviews has product_id and rating.", output_description:"Return product_id and average_rating ordered by product_id.", public_input:[{product_id:1,rating:4},{product_id:1,rating:2},{product_id:2,rating:5}], public_expected:[{product_id:1,average_rating:3},{product_id:2,average_rating:5}], cases:[{input:[{product_id:7,rating:3},{product_id:7,rating:5}],expected:[{product_id:7,average_rating:4}],ordered:true},{input:[{product_id:8,rating:1}],expected:[{product_id:8,average_rating:1}],ordered:true}], reference_solution:"from pyspark.sql import functions as F\ndef level_b_03_average_rating(reviews):\n    return reviews.groupBy(\"product_id\").agg(F.avg(\"rating\").alias(\"average_rating\")).orderBy(\"product_id\")\n", explanation:"avg() computes a numeric mean per group. The result remains a DataFrame and is sorted for stable presentation.", hints:["Group reviews by product_id.","Use F.avg() and alias the output average_rating."] },
  { id:"pyspark-b04-left-join-departments", learning_level:"B", title:"Keep every department", topic:"Joins", subtopic:"left join", function_name:"level_b_04_department_headcount", params:["departments","employees"], input_description:"departments has department_id/name; employees has employee_id/department_id.", output_description:"Return department_name and employee_count, including empty departments.", public_input:{departments:[{department_id:1,department_name:"Data"},{department_id:2,department_name:"Sales"}],employees:[{employee_id:1,department_id:1}]}, public_expected:[{department_name:"Data",employee_count:1},{department_name:"Sales",employee_count:0}], cases:[{input:{departments:[{department_id:3,department_name:"Ops"}],employees:[]},expected:[{department_name:"Ops",employee_count:0}],ordered:true},{input:{departments:[{department_id:4,department_name:"HR"}],employees:[{employee_id:2,department_id:4},{employee_id:3,department_id:4}]},expected:[{department_name:"HR",employee_count:2}],ordered:true}], reference_solution:"from pyspark.sql import functions as F\ndef level_b_04_department_headcount(departments, employees):\n    return (departments.join(employees, \"department_id\", \"left\")\n            .groupBy(\"department_name\")\n            .agg(F.count(\"employee_id\").alias(\"employee_count\"))\n            .orderBy(\"department_name\"))\n", explanation:"A left join retains each department even when no employee matches. Counting a nullable employee_id returns zero for an empty group.", hints:["Start from departments and left-join employees.","Count employee_id rather than count('*')."] },
  { id:"pyspark-b05-rank-by-team", learning_level:"B", title:"Rank players within each team", topic:"Window functions", subtopic:"rank", function_name:"level_b_05_rank_players", params:["players"], input_description:"players has player_id, team, points.", output_description:"Add team_rank using descending points; preserve rows and order by team then player_id.", public_input:[{player_id:1,team:"A",points:20},{player_id:2,team:"A",points:12},{player_id:3,team:"B",points:18}], public_expected:[{player_id:1,team:"A",points:20,team_rank:1},{player_id:2,team:"A",points:12,team_rank:2},{player_id:3,team:"B",points:18,team_rank:1}], cases:[{input:[{player_id:4,team:"C",points:9},{player_id:5,team:"C",points:7}],expected:[{player_id:4,team:"C",points:9,team_rank:1},{player_id:5,team:"C",points:7,team_rank:2}],ordered:true},{input:[{player_id:6,team:"D",points:10}],expected:[{player_id:6,team:"D",points:10,team_rank:1}],ordered:true}], reference_solution:"from pyspark.sql import functions as F\nfrom pyspark.sql.window import Window\ndef level_b_05_rank_players(players):\n    w = Window.partitionBy(\"team\").orderBy(F.desc(\"points\"))\n    return players.withColumn(\"team_rank\", F.rank().over(w)).orderBy(\"team\", \"player_id\")\n", explanation:"A window partitions rank calculation by team while keeping player detail rows.", hints:["Create a Window partitioned by team.","Order by points descending and apply rank()."] },
  { id:"pyspark-b06-latest-status", learning_level:"B", title:"Keep the latest status per device", topic:"Window functions", subtopic:"row_number", function_name:"level_b_06_latest_device_status", params:["events"], input_description:"events has device_id, event_time, status.", output_description:"Return only the newest row per device_id, ordered by device_id.", public_input:[{device_id:"d1",event_time:1,status:"new"},{device_id:"d1",event_time:3,status:"ready"},{device_id:"d2",event_time:2,status:"idle"}], public_expected:[{device_id:"d1",event_time:3,status:"ready"},{device_id:"d2",event_time:2,status:"idle"}], cases:[{input:[{device_id:"d3",event_time:4,status:"old"},{device_id:"d3",event_time:8,status:"new"}],expected:[{device_id:"d3",event_time:8,status:"new"}],ordered:true},{input:[{device_id:"d4",event_time:6,status:"ok"}],expected:[{device_id:"d4",event_time:6,status:"ok"}],ordered:true}], reference_solution:"from pyspark.sql import functions as F\nfrom pyspark.sql.window import Window\ndef level_b_06_latest_device_status(events):\n    w = Window.partitionBy(\"device_id\").orderBy(F.desc(\"event_time\"))\n    return (events.withColumn(\"rn\", F.row_number().over(w))\n            .filter(F.col(\"rn\") == 1).drop(\"rn\").orderBy(\"device_id\"))\n", explanation:"row_number() assigns one ordered position per device; filtering to 1 keeps the latest record.", hints:["Partition a window by device_id.","Sort newest first, add row_number, and keep row number 1."] },
  { id:"pyspark-b07-running-total", learning_level:"B", title:"Build an account running total", topic:"Window functions", subtopic:"rowsBetween", function_name:"level_b_07_running_total", params:["transactions"], input_description:"transactions has account_id, sequence_id, amount.", output_description:"Add running_total per account ordered by sequence_id.", public_input:[{account_id:"a",sequence_id:1,amount:5},{account_id:"a",sequence_id:2,amount:7}], public_expected:[{account_id:"a",sequence_id:1,amount:5,running_total:5},{account_id:"a",sequence_id:2,amount:7,running_total:12}], cases:[{input:[{account_id:"b",sequence_id:1,amount:2},{account_id:"b",sequence_id:2,amount:3}],expected:[{account_id:"b",sequence_id:1,amount:2,running_total:2},{account_id:"b",sequence_id:2,amount:3,running_total:5}],ordered:true},{input:[{account_id:"c",sequence_id:1,amount:9}],expected:[{account_id:"c",sequence_id:1,amount:9,running_total:9}],ordered:true}], reference_solution:"from pyspark.sql import functions as F\nfrom pyspark.sql.window import Window\ndef level_b_07_running_total(transactions):\n    w = Window.partitionBy(\"account_id\").orderBy(\"sequence_id\").rowsBetween(Window.unboundedPreceding, Window.currentRow)\n    return transactions.withColumn(\"running_total\", F.sum(\"amount\").over(w)).orderBy(\"account_id\", \"sequence_id\")\n", explanation:"A cumulative window frame starts at the first row in each account and ends at the current row.", hints:["Partition by account_id and order by sequence_id.","Use sum(amount) over a rowsBetween frame from unbounded preceding to current row."] },
  { id:"pyspark-b08-conditional-category", learning_level:"B", title:"Assign order priority", topic:"Conditional columns", subtopic:"when chains", function_name:"level_b_08_order_priority", params:["orders"], input_description:"orders has order_id and amount.", output_description:"Add priority: high for >=500, medium for >=100, low otherwise.", public_input:[{order_id:1,amount:600},{order_id:2,amount:250},{order_id:3,amount:40}], public_expected:[{order_id:1,amount:600,priority:"high"},{order_id:2,amount:250,priority:"medium"},{order_id:3,amount:40,priority:"low"}], cases:[{input:[{order_id:4,amount:500}],expected:[{order_id:4,amount:500,priority:"high"}]},{input:[{order_id:5,amount:99}],expected:[{order_id:5,amount:99,priority:"low"}]}], reference_solution:"from pyspark.sql import functions as F\ndef level_b_08_order_priority(orders):\n    priority = F.when(F.col(\"amount\") >= 500, \"high\").when(F.col(\"amount\") >= 100, \"medium\").otherwise(\"low\")\n    return orders.withColumn(\"priority\", priority)\n", explanation:"Chained when() expressions test conditions in order. The first true condition determines the label.", hints:["Test the high threshold before the medium threshold.","End the chain with otherwise('low')."] },
  { id:"pyspark-b09-date-year", learning_level:"B", title:"Extract the event year", topic:"Date functions", subtopic:"to_date and year", function_name:"level_b_09_event_year", params:["events"], input_description:"events has event_id and event_date as yyyy-MM-dd text.", output_description:"Add event_year as an integer.", public_input:[{event_id:1,event_date:"2025-03-10"}], public_expected:[{event_id:1,event_date:"2025-03-10",event_year:2025}], cases:[{input:[{event_id:2,event_date:"2024-11-01"}],expected:[{event_id:2,event_date:"2024-11-01",event_year:2024}]},{input:[{event_id:3,event_date:"2026-01-01"}],expected:[{event_id:3,event_date:"2026-01-01",event_year:2026}]}], reference_solution:"from pyspark.sql import functions as F\ndef level_b_09_event_year(events):\n    return events.withColumn(\"event_year\", F.year(F.to_date(\"event_date\")))\n", explanation:"Convert date text with to_date(), then extract its year using a Spark SQL function.", hints:["Parse event_date with F.to_date().","Pass the parsed date to F.year()."] },
  { id:"pyspark-b10-month-pivot", learning_level:"B", title:"Pivot monthly sales", topic:"Reshaping", subtopic:"pivot", function_name:"level_b_10_monthly_pivot", params:["sales"], input_description:"sales has store, month (Jan or Feb), amount.", output_description:"One row per store with Jan and Feb amount columns.", public_input:[{store:"A",month:"Jan",amount:5},{store:"A",month:"Feb",amount:7},{store:"B",month:"Jan",amount:3}], public_expected:[{store:"A",Jan:5,Feb:7},{store:"B",Jan:3,Feb:null}], cases:[{input:[{store:"C",month:"Feb",amount:8}],expected:[{store:"C",Jan:null,Feb:8}]},{input:[{store:"D",month:"Jan",amount:4},{store:"D",month:"Jan",amount:6}],expected:[{store:"D",Jan:10,Feb:null}]}], reference_solution:"from pyspark.sql import functions as F\ndef level_b_10_monthly_pivot(sales):\n    return sales.groupBy(\"store\").pivot(\"month\", [\"Jan\", \"Feb\"]).agg(F.sum(\"amount\"))\n", explanation:"pivot() turns category values into columns. Aggregation is needed when several rows share a store/month pair.", hints:["Group by store before pivoting month.","Use sum(amount) for each month and provide the pivot values."] },
  { id:"pyspark-b11-explode-tags", learning_level:"B", title:"Create one row per tag", topic:"Arrays", subtopic:"explode", function_name:"level_b_11_explode_tags", params:["articles"], input_description:"articles has article_id and a tags array.", output_description:"Return article_id and tag, one row per tag, sorted by article_id and tag.", public_input:[{article_id:1,tags:["spark","sql"]},{article_id:2,tags:["python"]}], public_expected:[{article_id:1,tag:"spark"},{article_id:1,tag:"sql"},{article_id:2,tag:"python"}], cases:[{input:[{article_id:3,tags:["etl","batch"]}],expected:[{article_id:3,tag:"batch"},{article_id:3,tag:"etl"}],ordered:true},{input:[{article_id:4,tags:["data"]}],expected:[{article_id:4,tag:"data"}],ordered:true}], reference_solution:"from pyspark.sql import functions as F\ndef level_b_11_explode_tags(articles):\n    return articles.select(\"article_id\", F.explode(\"tags\").alias(\"tag\")).orderBy(\"article_id\", \"tag\")\n", explanation:"explode() converts each array element into a row while repeating the other selected columns.", hints:["Select article_id and explode(tags).","Alias the exploded field tag and sort the output."] },
  { id:"pyspark-b12-json-fields", learning_level:"B", title:"Read fields from a JSON column", topic:"JSON functions", subtopic:"get_json_object", function_name:"level_b_12_extract_json", params:["logs"], input_description:"logs has log_id and payload_json strings with action and user fields.", output_description:"Add action and user_name extracted from the JSON text.", public_input:[{log_id:1,payload_json:"{\"action\":\"login\",\"user\":\"Mia\"}"}], public_expected:[{log_id:1,payload_json:"{\"action\":\"login\",\"user\":\"Mia\"}",action:"login",user_name:"Mia"}], cases:[{input:[{log_id:2,payload_json:"{\"action\":\"view\",\"user\":\"Bo\"}"}],expected:[{log_id:2,payload_json:"{\"action\":\"view\",\"user\":\"Bo\"}",action:"view",user_name:"Bo"}]},{input:[{log_id:3,payload_json:"{\"action\":\"buy\",\"user\":\"Kai\"}"}],expected:[{log_id:3,payload_json:"{\"action\":\"buy\",\"user\":\"Kai\"}",action:"buy",user_name:"Kai"}]}], reference_solution:"from pyspark.sql import functions as F\ndef level_b_12_extract_json(logs):\n    return (logs.withColumn(\"action\", F.get_json_object(\"payload_json\", \"$.action\"))\n            .withColumn(\"user_name\", F.get_json_object(\"payload_json\", \"$.user\")))\n", explanation:"get_json_object() reads a JSON path from a string column and returns a Spark string column.", hints:["Use get_json_object on payload_json.","Extract $.action and $.user into named columns."] },
  { id:"pyspark-b13-top-two-products", learning_level:"B", title:"Keep the top two products per category", topic:"Window functions", subtopic:"row_number", function_name:"level_b_13_top_products", params:["products"], input_description:"products has product_id, category, sales.", output_description:"Keep the two highest-sales products per category, ordered by category and product_id.", public_input:[{product_id:1,category:"A",sales:30},{product_id:2,category:"A",sales:20},{product_id:3,category:"A",sales:10}], public_expected:[{product_id:1,category:"A",sales:30},{product_id:2,category:"A",sales:20}], cases:[{input:[{product_id:4,category:"B",sales:8},{product_id:5,category:"B",sales:12},{product_id:6,category:"B",sales:4}],expected:[{product_id:5,category:"B",sales:12},{product_id:4,category:"B",sales:8}],ordered:true},{input:[{product_id:7,category:"C",sales:3}],expected:[{product_id:7,category:"C",sales:3}],ordered:true}], reference_solution:"from pyspark.sql import functions as F\nfrom pyspark.sql.window import Window\ndef level_b_13_top_products(products):\n    w = Window.partitionBy(\"category\").orderBy(F.desc(\"sales\"))\n    return (products.withColumn(\"rn\", F.row_number().over(w))\n            .filter(F.col(\"rn\") <= 2).drop(\"rn\").orderBy(\"category\", \"product_id\"))\n", explanation:"row_number() creates a deterministic position within each category. Filtering to two retains the top two rows per group.", hints:["Partition a window by category and sort sales descending.","Add row_number, then keep rows with rn <= 2."] },
  { id:"pyspark-b14-union-events", learning_level:"B", title:"Combine daily event batches", topic:"DataFrame basics", subtopic:"unionByName", function_name:"level_b_14_union_events", params:["day_one","day_two"], input_description:"Both DataFrames have event_id and event_type columns.", output_description:"Combine both batches and order by event_id.", public_input:{day_one:[{event_id:1,event_type:"view"}],day_two:[{event_id:2,event_type:"click"}]}, public_expected:[{event_id:1,event_type:"view"},{event_id:2,event_type:"click"}], cases:[{input:{day_one:[{event_id:3,event_type:"buy"}],day_two:[{event_id:4,event_type:"view"}]},expected:[{event_id:3,event_type:"buy"},{event_id:4,event_type:"view"}],ordered:true},{input:{day_one:[{event_id:5,event_type:"click"}],day_two:[{event_id:6,event_type:"click"}]},expected:[{event_id:5,event_type:"click"},{event_id:6,event_type:"click"}],ordered:true}], reference_solution:"def level_b_14_union_events(day_one, day_two):\n    return day_one.unionByName(day_two).orderBy(\"event_id\")\n", explanation:"unionByName() appends rows from another DataFrame by matching column names rather than position.", hints:["Use unionByName() on the first batch.","Sort the combined DataFrame by event_id."] },
  { id:"pyspark-b15-left-anti", learning_level:"B", title:"Find customers with no orders", topic:"Joins", subtopic:"left anti join", function_name:"level_b_15_customers_without_orders", params:["customers","orders"], input_description:"customers has customer_id/name; orders has customer_id.", output_description:"Return customers with no matching order, with customer_id and name sorted by id.", public_input:{customers:[{customer_id:1,name:"Ada"},{customer_id:2,name:"Bo"}],orders:[{customer_id:1}]}, public_expected:[{customer_id:2,name:"Bo"}], cases:[{input:{customers:[{customer_id:3,name:"Cy"}],orders:[]},expected:[{customer_id:3,name:"Cy"}],ordered:true},{input:{customers:[{customer_id:4,name:"Dee"}],orders:[{customer_id:4}]},expected:[],ordered:true}], reference_solution:"def level_b_15_customers_without_orders(customers, orders):\n    return (customers.join(orders.select(\"customer_id\").distinct(), \"customer_id\", \"left_anti\")\n            .select(\"customer_id\", \"name\").orderBy(\"customer_id\"))\n", explanation:"A left anti join returns left-side rows with no match on the right, a direct pattern for finding missing relationships.", hints:["Join customers to the distinct order customer IDs.","Choose left_anti as the join type."] }
];

const levelC: SparkQuestion[] = [
  { id:"pyspark-c01-cumulative-revenue", learning_level:"C", title:"Calculate cumulative revenue per shop", topic:"Window functions", subtopic:"running sum", function_name:"level_c_01_cumulative_revenue", params:["sales"], input_description:"sales has shop, sequence_id, amount.", output_description:"Add cumulative_revenue per shop ordered by sequence_id.", public_input:[{shop:"A",sequence_id:1,amount:4},{shop:"A",sequence_id:2,amount:6}], public_expected:[{shop:"A",sequence_id:1,amount:4,cumulative_revenue:4},{shop:"A",sequence_id:2,amount:6,cumulative_revenue:10}], cases:[{input:[{shop:"B",sequence_id:1,amount:3},{shop:"B",sequence_id:2,amount:2}],expected:[{shop:"B",sequence_id:1,amount:3,cumulative_revenue:3},{shop:"B",sequence_id:2,amount:2,cumulative_revenue:5}],ordered:true},{input:[{shop:"C",sequence_id:1,amount:9}],expected:[{shop:"C",sequence_id:1,amount:9,cumulative_revenue:9}],ordered:true}], reference_solution:"from pyspark.sql import functions as F\nfrom pyspark.sql.window import Window\ndef level_c_01_cumulative_revenue(sales):\n    w = Window.partitionBy(\"shop\").orderBy(\"sequence_id\").rowsBetween(Window.unboundedPreceding, Window.currentRow)\n    return sales.withColumn(\"cumulative_revenue\", F.sum(\"amount\").over(w)).orderBy(\"shop\", \"sequence_id\")\n", explanation:"An explicit window frame computes cumulative totals independently for each shop and preserves row-level detail.", hints:["Partition by shop and order by sequence_id.","Use sum(amount) over an unbounded-preceding frame ending at the current row."] },
  { id:"pyspark-c02-three-row-average", learning_level:"C", title:"Compute a trailing three-row average", topic:"Window functions", subtopic:"moving average", function_name:"level_c_02_trailing_average", params:["measurements"], input_description:"measurements has sensor_id, sequence_id, value.", output_description:"Add trailing_avg over the current row and previous two rows per sensor.", public_input:[{sensor_id:"s",sequence_id:1,value:3},{sensor_id:"s",sequence_id:2,value:6},{sensor_id:"s",sequence_id:3,value:9}], public_expected:[{sensor_id:"s",sequence_id:1,value:3,trailing_avg:3},{sensor_id:"s",sequence_id:2,value:6,trailing_avg:4.5},{sensor_id:"s",sequence_id:3,value:9,trailing_avg:6}], cases:[{input:[{sensor_id:"t",sequence_id:1,value:2},{sensor_id:"t",sequence_id:2,value:4}],expected:[{sensor_id:"t",sequence_id:1,value:2,trailing_avg:2},{sensor_id:"t",sequence_id:2,value:4,trailing_avg:3}],ordered:true},{input:[{sensor_id:"u",sequence_id:1,value:5},{sensor_id:"u",sequence_id:2,value:8},{sensor_id:"u",sequence_id:3,value:11}],expected:[{sensor_id:"u",sequence_id:1,value:5,trailing_avg:5},{sensor_id:"u",sequence_id:2,value:8,trailing_avg:6.5},{sensor_id:"u",sequence_id:3,value:11,trailing_avg:8}],ordered:true}], reference_solution:"from pyspark.sql import functions as F\nfrom pyspark.sql.window import Window\ndef level_c_02_trailing_average(measurements):\n    w = Window.partitionBy(\"sensor_id\").orderBy(\"sequence_id\").rowsBetween(-2, Window.currentRow)\n    return measurements.withColumn(\"trailing_avg\", F.avg(\"value\").over(w)).orderBy(\"sensor_id\", \"sequence_id\")\n", explanation:"A bounded rowsBetween(-2, currentRow) frame includes at most three sequential rows for each sensor.", hints:["Define a sensor-partitioned ordered window.","Set the frame from -2 to current row and average value."] },
  { id:"pyspark-c03-full-outer", learning_level:"C", title:"Reconcile source and target IDs", topic:"Joins", subtopic:"full outer join", function_name:"level_c_03_reconcile_ids", params:["source","target"], input_description:"source and target each have record_id and amount.", output_description:"Return record_id, source_amount, target_amount for every ID from either side.", public_input:{source:[{record_id:1,amount:10},{record_id:2,amount:20}],target:[{record_id:2,amount:20},{record_id:3,amount:30}]}, public_expected:[{record_id:1,source_amount:10,target_amount:null},{record_id:2,source_amount:20,target_amount:20},{record_id:3,source_amount:null,target_amount:30}], cases:[{input:{source:[{record_id:4,amount:5}],target:[{record_id:4,amount:5}]},expected:[{record_id:4,source_amount:5,target_amount:5}]},{input:{source:[],target:[{record_id:5,amount:8}]},expected:[{record_id:5,source_amount:null,target_amount:8}]}], reference_solution:"from pyspark.sql import functions as F\ndef level_c_03_reconcile_ids(source, target):\n    left = source.select(\"record_id\", F.col(\"amount\").alias(\"source_amount\"))\n    right = target.select(\"record_id\", F.col(\"amount\").alias(\"target_amount\"))\n    return left.join(right, \"record_id\", \"full_outer\").select(\"record_id\", \"source_amount\", \"target_amount\")\n", explanation:"A full outer join preserves matched and unmatched keys from both sides, which is useful for reconciliation.", hints:["Rename amount on each side before joining.","Use a full_outer join on record_id."] },
  { id:"pyspark-c04-percent-of-category", learning_level:"C", title:"Calculate each product's share of category sales", topic:"Window functions", subtopic:"percentage of total", function_name:"level_c_04_category_share", params:["products"], input_description:"products has category, product_id, sales.", output_description:"Add category_total and share_percent (0-100), ordered by category and product.", public_input:[{category:"A",product_id:1,sales:30},{category:"A",product_id:2,sales:70}], public_expected:[{category:"A",product_id:1,sales:30,category_total:100,share_percent:30},{category:"A",product_id:2,sales:70,category_total:100,share_percent:70}], cases:[{input:[{category:"B",product_id:3,sales:2},{category:"B",product_id:4,sales:2}],expected:[{category:"B",product_id:3,sales:2,category_total:4,share_percent:50},{category:"B",product_id:4,sales:2,category_total:4,share_percent:50}],ordered:true},{input:[{category:"C",product_id:5,sales:9}],expected:[{category:"C",product_id:5,sales:9,category_total:9,share_percent:100}],ordered:true}], reference_solution:"from pyspark.sql import functions as F\nfrom pyspark.sql.window import Window\ndef level_c_04_category_share(products):\n    w = Window.partitionBy(\"category\")\n    return (products.withColumn(\"category_total\", F.sum(\"sales\").over(w))\n            .withColumn(\"share_percent\", F.col(\"sales\") / F.col(\"category_total\") * 100)\n            .orderBy(\"category\", \"product_id\"))\n", explanation:"A partition-only window gives each row its category total without collapsing products. Dividing each sale by that total yields its percentage.", hints:["Calculate sum(sales) over a window partitioned by category.","Divide sales by the new total and multiply by 100."] },
  { id:"pyspark-c05-dedupe-latest", learning_level:"C", title:"Deduplicate events by latest timestamp", topic:"Data quality", subtopic:"deterministic deduplication", function_name:"level_c_05_dedupe_latest", params:["events"], input_description:"events has event_id, event_time, payload.", output_description:"Keep the newest row per event_id, tie-breaking by payload ascending.", public_input:[{event_id:"e1",event_time:1,payload:"old"},{event_id:"e1",event_time:3,payload:"new"},{event_id:"e2",event_time:2,payload:"only"}], public_expected:[{event_id:"e1",event_time:3,payload:"new"},{event_id:"e2",event_time:2,payload:"only"}], cases:[{input:[{event_id:"e3",event_time:2,payload:"a"},{event_id:"e3",event_time:2,payload:"b"}],expected:[{event_id:"e3",event_time:2,payload:"a"}]},{input:[{event_id:"e4",event_time:1,payload:"x"},{event_id:"e4",event_time:5,payload:"z"}],expected:[{event_id:"e4",event_time:5,payload:"z"}]}], reference_solution:"from pyspark.sql import functions as F\nfrom pyspark.sql.window import Window\ndef level_c_05_dedupe_latest(events):\n    w = Window.partitionBy(\"event_id\").orderBy(F.desc(\"event_time\"), F.asc(\"payload\"))\n    return (events.withColumn(\"rn\", F.row_number().over(w))\n            .filter(F.col(\"rn\") == 1).drop(\"rn\").orderBy(\"event_id\"))\n", explanation:"A deterministic window ordering selects one latest record per event, including a defined tie-breaker when timestamps match.", hints:["Partition by event_id and order newest first.","Add payload as a stable second sort key, then keep row_number 1."] },
  { id:"pyspark-c06-null-safe-total", learning_level:"C", title:"Total payments while handling null amounts", topic:"Null handling", subtopic:"coalesce and aggregation", function_name:"level_c_06_customer_totals", params:["payments"], input_description:"payments has customer_id and nullable amount.", output_description:"Return each customer_id and total_amount, treating null amount as zero.", public_input:[{customer_id:1,amount:10},{customer_id:1,amount:null},{customer_id:2,amount:5}], public_expected:[{customer_id:1,total_amount:10},{customer_id:2,total_amount:5}], cases:[{input:[{customer_id:3,amount:null}],expected:[{customer_id:3,total_amount:0}]},{input:[{customer_id:4,amount:2},{customer_id:4,amount:3}],expected:[{customer_id:4,total_amount:5}]}], reference_solution:"from pyspark.sql import functions as F\ndef level_c_06_customer_totals(payments):\n    clean = payments.withColumn(\"amount\", F.coalesce(F.col(\"amount\"), F.lit(0)))\n    return clean.groupBy(\"customer_id\").agg(F.sum(\"amount\").alias(\"total_amount\"))\n", explanation:"Normalize null amounts before aggregation so missing values contribute zero rather than disappearing from business totals.", hints:["Use coalesce to replace null with integer zero.","Then group by customer_id and sum the cleaned amount."] },
  { id:"pyspark-c07-lag-change", learning_level:"C", title:"Compare each reading with its previous value", topic:"Window functions", subtopic:"lag", function_name:"level_c_07_reading_change", params:["readings"], input_description:"readings has sensor_id, sequence_id and value.", output_description:"Add previous_value and change; the first row per sensor has null previous_value and change.", public_input:[{sensor_id:"s",sequence_id:1,value:10},{sensor_id:"s",sequence_id:2,value:15}], public_expected:[{sensor_id:"s",sequence_id:1,value:10,previous_value:null,change:null},{sensor_id:"s",sequence_id:2,value:15,previous_value:10,change:5}], cases:[{input:[{sensor_id:"t",sequence_id:1,value:4},{sensor_id:"t",sequence_id:2,value:9}],expected:[{sensor_id:"t",sequence_id:1,value:4,previous_value:null,change:null},{sensor_id:"t",sequence_id:2,value:9,previous_value:4,change:5}],ordered:true},{input:[{sensor_id:"u",sequence_id:1,value:3}],expected:[{sensor_id:"u",sequence_id:1,value:3,previous_value:null,change:null}],ordered:true}], reference_solution:"from pyspark.sql import functions as F\nfrom pyspark.sql.window import Window\ndef level_c_07_reading_change(readings):\n    w = Window.partitionBy(\"sensor_id\").orderBy(\"sequence_id\")\n    result = readings.withColumn(\"previous_value\", F.lag(\"value\").over(w))\n    return result.withColumn(\"change\", F.col(\"value\") - F.col(\"previous_value\")).orderBy(\"sensor_id\", \"sequence_id\")\n", explanation:"lag() exposes a prior row's value within an ordered partition, enabling per-entity change calculations.", hints:["Define an ordered window for each sensor.","Use lag(value), then subtract previous_value from value."] },
  { id:"pyspark-c08-left-anti", learning_level:"C", title:"Find products never sold", topic:"Joins", subtopic:"left anti join", function_name:"level_c_08_unsold_products", params:["products","order_lines"], input_description:"products has product_id/name; order_lines has product_id.", output_description:"Return products with no matching order line, ordered by product_id.", public_input:{products:[{product_id:1,name:"Pen"},{product_id:2,name:"Book"}],order_lines:[{product_id:1}]}, public_expected:[{product_id:2,name:"Book"}], cases:[{input:{products:[{product_id:3,name:"Cup"}],order_lines:[]},expected:[{product_id:3,name:"Cup"}],ordered:true},{input:{products:[{product_id:4,name:"Bag"}],order_lines:[{product_id:4}]},expected:[],ordered:true}], reference_solution:"def level_c_08_unsold_products(products, order_lines):\n    sold = order_lines.select(\"product_id\").distinct()\n    return products.join(sold, \"product_id\", \"left_anti\").orderBy(\"product_id\")\n", explanation:"A left anti join is efficient for expressing records from one DataFrame that have no key match in another.", hints:["Select distinct product IDs from order lines.","Join products to that set using left_anti."] },
  { id:"pyspark-c09-prior-month", learning_level:"C", title:"Compare monthly sales with prior month", topic:"Window functions", subtopic:"lag and percentage change", function_name:"level_c_09_month_change", params:["sales"], input_description:"sales has store, month_number, amount.", output_description:"Add prior_amount and percent_change per store; first month's percent_change is null.", public_input:[{store:"A",month_number:1,amount:100},{store:"A",month_number:2,amount:120}], public_expected:[{store:"A",month_number:1,amount:100,prior_amount:null,percent_change:null},{store:"A",month_number:2,amount:120,prior_amount:100,percent_change:20}], cases:[{input:[{store:"B",month_number:1,amount:50},{store:"B",month_number:2,amount:75}],expected:[{store:"B",month_number:1,amount:50,prior_amount:null,percent_change:null},{store:"B",month_number:2,amount:75,prior_amount:50,percent_change:50}],ordered:true},{input:[{store:"C",month_number:1,amount:80}],expected:[{store:"C",month_number:1,amount:80,prior_amount:null,percent_change:null}],ordered:true}], reference_solution:"from pyspark.sql import functions as F\nfrom pyspark.sql.window import Window\ndef level_c_09_month_change(sales):\n    w = Window.partitionBy(\"store\").orderBy(\"month_number\")\n    result = sales.withColumn(\"prior_amount\", F.lag(\"amount\").over(w))\n    change = (F.col(\"amount\") - F.col(\"prior_amount\")) / F.col(\"prior_amount\") * 100\n    return result.withColumn(\"percent_change\", change).orderBy(\"store\", \"month_number\")\n", explanation:"lag() aligns each month with its prior value; percentage change is relative to that prior amount.", hints:["Create a store-partitioned monthly window.","Compute lag(amount), then divide the difference by prior_amount and multiply by 100."] },
  { id:"pyspark-c10-grouping-counts", learning_level:"C", title:"Aggregate orders by region and status", topic:"Aggregations", subtopic:"multi-column groupBy", function_name:"level_c_10_region_status", params:["orders"], input_description:"orders has region and status strings.", output_description:"Return region, status and order_count, sorted by region/status.", public_input:[{region:"East",status:"new"},{region:"East",status:"new"},{region:"West",status:"done"}], public_expected:[{region:"East",status:"new",order_count:2},{region:"West",status:"done",order_count:1}], cases:[{input:[{region:"North",status:"open"}],expected:[{region:"North",status:"open",order_count:1}],ordered:true},{input:[{region:"South",status:"done"},{region:"South",status:"done"}],expected:[{region:"South",status:"done",order_count:2}],ordered:true}], reference_solution:"from pyspark.sql import functions as F\ndef level_c_10_region_status(orders):\n    return (orders.groupBy(\"region\", \"status\")\n            .agg(F.count(\"*\").alias(\"order_count\"))\n            .orderBy(\"region\", \"status\"))\n", explanation:"Grouping by multiple keys creates one aggregate row per distinct region/status combination.", hints:["Pass both region and status to groupBy().","Count rows and give the result the requested alias."] },
  { id:"pyspark-c11-bucket-size", learning_level:"C", title:"Bucket events by volume", topic:"Conditional columns", subtopic:"when and otherwise", function_name:"level_c_11_volume_bucket", params:["events"], input_description:"events has event_id and bytes_processed.", output_description:"Add volume_band: small below 1000, medium below 10000, large otherwise.", public_input:[{event_id:1,bytes_processed:400},{event_id:2,bytes_processed:2500},{event_id:3,bytes_processed:12000}], public_expected:[{event_id:1,bytes_processed:400,volume_band:"small"},{event_id:2,bytes_processed:2500,volume_band:"medium"},{event_id:3,bytes_processed:12000,volume_band:"large"}], cases:[{input:[{event_id:4,bytes_processed:9999}],expected:[{event_id:4,bytes_processed:9999,volume_band:"medium"}]},{input:[{event_id:5,bytes_processed:10000}],expected:[{event_id:5,bytes_processed:10000,volume_band:"large"}]}], reference_solution:"from pyspark.sql import functions as F\ndef level_c_11_volume_bucket(events):\n    band = F.when(F.col(\"bytes_processed\") < 1000, \"small\").when(F.col(\"bytes_processed\") < 10000, \"medium\").otherwise(\"large\")\n    return events.withColumn(\"volume_band\", band)\n", explanation:"Ordered conditional expressions make range boundaries explicit and keep classification distributed in Spark.", hints:["Test the smallest range first.","Add a second when() for medium and otherwise classify as large."] },
  { id:"pyspark-c12-window-previous-next", learning_level:"C", title:"Show previous and next trip fare", topic:"Window functions", subtopic:"lag and lead", function_name:"level_c_12_neighbor_fares", params:["trips"], input_description:"trips has rider_id, trip_number and fare.", output_description:"Add previous_fare and next_fare per rider, ordered by trip_number.", public_input:[{rider_id:"r",trip_number:1,fare:10},{rider_id:"r",trip_number:2,fare:14},{rider_id:"r",trip_number:3,fare:12}], public_expected:[{rider_id:"r",trip_number:1,fare:10,previous_fare:null,next_fare:14},{rider_id:"r",trip_number:2,fare:14,previous_fare:10,next_fare:12},{rider_id:"r",trip_number:3,fare:12,previous_fare:14,next_fare:null}], cases:[{input:[{rider_id:"s",trip_number:1,fare:3},{rider_id:"s",trip_number:2,fare:5}],expected:[{rider_id:"s",trip_number:1,fare:3,previous_fare:null,next_fare:5},{rider_id:"s",trip_number:2,fare:5,previous_fare:3,next_fare:null}],ordered:true},{input:[{rider_id:"t",trip_number:1,fare:7}],expected:[{rider_id:"t",trip_number:1,fare:7,previous_fare:null,next_fare:null}],ordered:true}], reference_solution:"from pyspark.sql import functions as F\nfrom pyspark.sql.window import Window\ndef level_c_12_neighbor_fares(trips):\n    w = Window.partitionBy(\"rider_id\").orderBy(\"trip_number\")\n    return (trips.withColumn(\"previous_fare\", F.lag(\"fare\").over(w))\n            .withColumn(\"next_fare\", F.lead(\"fare\").over(w))\n            .orderBy(\"rider_id\", \"trip_number\"))\n", explanation:"lag() reads a previous row and lead() reads a following row within the same ordered rider partition.", hints:["Use a rider-partitioned window ordered by trip_number.","Add both lag(fare) and lead(fare) with the requested aliases."] },
  { id:"pyspark-c13-sum-after-explode", learning_level:"C", title:"Total item quantities per basket", topic:"Arrays", subtopic:"explode and groupBy", function_name:"level_c_13_basket_totals", params:["baskets"], input_description:"baskets has basket_id and an items array of item_name/quantity structs.", output_description:"Return basket_id and total_quantity.", public_input:[{basket_id:1,items:[{item_name:"pen",quantity:2},{item_name:"book",quantity:1}]}], public_expected:[{basket_id:1,total_quantity:3}], cases:[{input:[{basket_id:2,items:[{item_name:"cup",quantity:4}]}],expected:[{basket_id:2,total_quantity:4}]},{input:[{basket_id:3,items:[{item_name:"a",quantity:1},{item_name:"b",quantity:2}]}],expected:[{basket_id:3,total_quantity:3}]}], reference_solution:"from pyspark.sql import functions as F\ndef level_c_13_basket_totals(baskets):\n    items = baskets.select(\"basket_id\", F.explode(\"items\").alias(\"item\"))\n    return items.groupBy(\"basket_id\").agg(F.sum(\"item.quantity\").alias(\"total_quantity\"))\n", explanation:"Explode nested item arrays into rows, then aggregate quantities back to basket level.", hints:["Explode items and keep basket_id.","Sum the nested quantity field by basket_id."] },
  { id:"pyspark-c14-join-reconcile", learning_level:"C", title:"Flag mismatched source and target values", topic:"Data quality", subtopic:"full join and when", function_name:"level_c_14_reconcile_amounts", params:["source","target"], input_description:"Both DataFrames have record_id and amount.", output_description:"Return record_id and status: missing_source, missing_target, match, or mismatch.", public_input:{source:[{record_id:1,amount:10},{record_id:2,amount:20}],target:[{record_id:1,amount:10},{record_id:2,amount:25},{record_id:3,amount:30}]}, public_expected:[{record_id:1,status:"match"},{record_id:2,status:"mismatch"},{record_id:3,status:"missing_source"}], cases:[{input:{source:[{record_id:4,amount:2}],target:[{record_id:4,amount:3}]},expected:[{record_id:4,status:"mismatch"}]},{input:{source:[],target:[{record_id:5,amount:9}]},expected:[{record_id:5,status:"missing_source"}]}], reference_solution:"from pyspark.sql import functions as F\ndef level_c_14_reconcile_amounts(source, target):\n    left = source.select(\"record_id\", F.col(\"amount\").alias(\"source_amount\"))\n    right = target.select(\"record_id\", F.col(\"amount\").alias(\"target_amount\"))\n    joined = left.join(right, \"record_id\", \"full_outer\")\n    status = (F.when(F.col(\"source_amount\").isNull(), \"missing_source\")\n              .when(F.col(\"target_amount\").isNull(), \"missing_target\")\n              .when(F.col(\"source_amount\") == F.col(\"target_amount\"), \"match\")\n              .otherwise(\"mismatch\"))\n    return joined.select(\"record_id\", status.alias(\"status\")).orderBy(\"record_id\")\n", explanation:"A full outer join exposes missing keys on either side. Conditional logic then distinguishes missing records from matching or differing values.", hints:["Keep source/target amounts under different names.","Full-join by record_id and check null sides before comparing values."] },
  { id:"pyspark-c15-partitioned-summary", learning_level:"C", title:"Summarize revenue by month and region", topic:"Performance patterns", subtopic:"filter then aggregate", function_name:"level_c_15_month_region_summary", params:["sales"], input_description:"sales has sale_date (yyyy-MM-dd text), region and amount.", output_description:"Return sale_month, region, revenue for dates in 2025, sorted by month/region.", public_input:[{sale_date:"2025-01-03",region:"East",amount:10},{sale_date:"2025-01-14",region:"East",amount:5},{sale_date:"2024-12-31",region:"East",amount:100}], public_expected:[{sale_month:"2025-01",region:"East",revenue:15}], cases:[{input:[{sale_date:"2025-02-01",region:"West",amount:7},{sale_date:"2024-02-01",region:"West",amount:90}],expected:[{sale_month:"2025-02",region:"West",revenue:7}],ordered:true},{input:[{sale_date:"2025-03-01",region:"North",amount:2}],expected:[{sale_month:"2025-03",region:"North",revenue:2}],ordered:true}], reference_solution:"from pyspark.sql import functions as F\ndef level_c_15_month_region_summary(sales):\n    filtered = sales.filter(F.year(F.to_date(\"sale_date\")) == 2025)\n    prepared = filtered.withColumn(\"sale_month\", F.date_format(F.to_date(\"sale_date\"), \"yyyy-MM\"))\n    return (prepared.groupBy(\"sale_month\", \"region\")\n            .agg(F.sum(\"amount\").alias(\"revenue\"))\n            .orderBy(\"sale_month\", \"region\"))\n", explanation:"Filter early to reduce data before aggregation, derive a month key, then group by month and region. Spark can optimize this relational plan.", hints:["Parse dates and filter to year 2025 before grouping.","Format a yyyy-MM key and sum amount per month/region."] }
];

export const beginnerSparkQuestions = levelA.map(buildQuestion);
